// resolveGitPushRemote reports the remote a bare `git push` on the current
// branch delivers to, following git's own precedence:
// branch.<name>.pushRemote, remote.pushDefault, branch.<name>.remote, origin.
//
// Deliberately separate from election: election answers "where do checkpoints
// go", this answers "where does the user's code go", and the whole point of the
// mismatch check is that those two can differ. Returns "" when the answer is
// unknowable (detached HEAD with nothing configured, unreadable config), which
// callers read as "do not compare".
func resolveGitPushRemote(ctx context.Context, dir string) string {
	branch, err := gitRunner(ctx, dir, "symbolic-ref", "--short", "HEAD")
	if err != nil {
		// Detached HEAD: no branch config to consult, but the repo-wide
		// pushDefault still decides, so keep going with an empty branch name.
		branch = ""
	}

	keys := []string{"remote.pushDefault"}
	if branch != "" {
		keys = []string{
			"branch." + branch + ".pushRemote",
			"remote.pushDefault",
			"branch." + branch + ".remote",
		}
	}
	for _, key := range keys {
		if v, err := gitRunner(ctx, dir, "config", "--get", key); err == nil && v != "" {
			return v
		}
	}

	// Git's final fallback. Reported only when it exists, so a repo without an
	// origin yields "" instead of naming a remote that is not there.
	for _, d := range t0Destinations(ctx, dir) {
		if d == "origin" {
			return "origin"
		}
	}
	return ""
}

