// resolveGitPushRemote can check for origin without threading the already-parsed
// topology through, keeping it usable on its own.
func t0Destinations(ctx context.Context, dir string) []string {
	out, err := gitRunner(ctx, dir, "remote")
	if err != nil {
		return nil
	}
	var names []string
	for _, line := range strings.Split(out, "\n") {
		if name := strings.TrimSpace(line); name != "" {
			names = append(names, name)
		}
	}
	return names
}

