// destinationPinned reports that the user has already chosen where checkpoints
// go, either with checkpoint_push_remote (election says "config") or by pinning
// every remote to a checkpoint_remote. Such a repo is settled: it gets no
// "choose a destination" advice, because the choice is made.
//
// This is the check whose absence made the note misfire — a repo with
// checkpoint_push_remote correctly set was still told to go and set something.
func (t remoteTopology) destinationPinned() bool {
	if t.electedSource == strategy.SyncRemoteSourceConfig {
		return true
	}
	for _, d := range t.destinations {
		if !d.pinned {
			return false
		}
	}
	return len(t.destinations) > 0
}

// pushMismatch reports the case that silently loses checkpoints: `git push`
// lands on a remote that is not the elected checkpoint sync remote, so the push
// carries no checkpoint data at all. Both names must be known for the
// comparison to mean anything.
func (t remoteTopology) pushMismatch() bool {
	return t.elected != "" && t.pushDest != "" && t.elected != t.pushDest
}

// fansOutSomewhere reports whether any remote's checkpoints face several push URLs.
func (t remoteTopology) fansOutSomewhere() bool {
	for _, d := range t.destinations {
		if d.fansOut() {
			return true
		}
	}
	return false
}

// worthReporting reports whether anything here needs saying: a push that
// carries no checkpoints, a fail-closed election, a remote whose checkpoints fan
// out over several URLs, or an unsettled choice between several remotes.
func (t remoteTopology) worthReporting() bool {
	if t.pushMismatch() || t.electionErr != "" || t.fansOutSomewhere() {
		return true
	}
	return len(t.unpinnedNames()) > 1 && !t.destinationPinned()
}

// describeCheckpointDestination writes an explanation of where checkpoints go,
// under the given header. Writes nothing when there is nothing to report.
func (t remoteTopology) describeCheckpointDestination(w io.Writer, header string) {
	if !t.worthReporting() {
		return
	}

	fmt.Fprintln(w, header)

	// The mismatch first: it is the only entry here that means checkpoints are
	// being lost right now, so it must not sit below the advisory paragraphs.
	if t.pushMismatch() {
		fmt.Fprintf(w, "  Your pushes are NOT carrying checkpoints.\n")
		fmt.Fprintf(w, "    `git push` goes to %q, but checkpoints sync only to %q", t.pushDest, t.elected)
		if t.electedSource == strategy.SyncRemoteSourceDefault {
			fmt.Fprintf(w, " (the default)")
		}
		fmt.Fprintf(w, ",\n    so a push to %q carries none.\n", t.pushDest)
		fmt.Fprintf(w, "    Fix: set \"strategy_options\": {\"checkpoint_push_remote\": %q} in\n", t.pushDest)
		fmt.Fprintln(w, "    .entire/settings.json (or .entire/settings.local.json for this clone only).")
	}

	if t.electionErr != "" {
		fmt.Fprintln(w, "  Checkpoints are NOT syncing anywhere:")
		fmt.Fprintf(w, "    %s\n", t.electionErr)
		fmt.Fprintln(w, "    Fix: point checkpoint_push_remote at a remote that exists, or remove it")
		fmt.Fprintln(w, "    to fall back to the default election.")
	}

	for _, d := range t.destinations {
		if !d.fansOut() {
			continue
		}
		fmt.Fprintf(w, "  Remote %q pushes to %d URLs:\n", d.name, len(d.pushURLs))
		for i, u := range d.pushURLs {
			marker := "  "
			if i == 0 && t.primaryIsRefs {
				marker = "→ "
			}
			fmt.Fprintf(w, "    %s%s\n", marker, gitremote.RedactURLOrPath(u))
		}
		if t.primaryIsRefs {
			fmt.Fprintln(w, "    Checkpoints go to the first URL only; the others receive your code but")
			fmt.Fprintln(w, "    no session history. Clone that first repository to resume elsewhere.")
		} else {
			fmt.Fprintln(w, "    Checkpoints are pushed to every URL. If one rejects them or is")
			fmt.Fprintln(w, "    unreachable it is reported and left behind, and only the fetch URL is")
			fmt.Fprintln(w, "    ever reconciled — so those URLs can fall permanently out of date.")
		}
	}

	// Several remotes and no explicit choice: state the election outcome rather
	// than the old (and since the single-remote gate, false) claim that
	// checkpoints follow whichever remote you push to.
	if names := t.unpinnedNames(); len(names) > 1 && !t.destinationPinned() {
		fmt.Fprintf(w, "  This repo has %d remotes (%s).\n", len(names), strings.Join(names, ", "))
		if t.elected != "" {
			fmt.Fprintf(w, "    Checkpoints sync only to %q; a push to any other remote carries none.\n", t.elected)
		}
		fmt.Fprintln(w, "    Reading them back (resume, explain) also looks at origin, so checkpoints")
		fmt.Fprintln(w, "    kept anywhere else are not found again from this clone.")
		fmt.Fprintln(w, "    To choose the remote deliberately, set checkpoint_push_remote in")
		fmt.Fprintln(w, "    .entire/settings.json (or .entire/settings.local.json for this clone only).")
	}

	if t.fansOutSomewhere() {
		fmt.Fprintln(w, "  To pin one repository for checkpoints, set checkpoint_remote in")
		fmt.Fprintln(w, "  .entire/settings.json (or .entire/settings.local.json to keep it to this clone).")
	}
}

