// checkpointNoteStyle selects how the destination note announces itself. The
// wording lives here rather than at the call sites on purpose: the caller-supplied
// header is how this note came to claim "checkpoints follow whichever remote you
// push to" long after the single-remote gate made that false.
type checkpointNoteStyle int

const (
	// noteStyleStatusLabel matches doctor's "<check>: <verdict>" lines.
	noteStyleStatusLabel checkpointNoteStyle = iota
	// noteStyleSentence matches the prose notes `entire enable` ends with, and
	// leads with a blank line to separate itself from the setup output.
	noteStyleSentence
)

// header phrases the note's opening line for the given style, escalating when
// the finding is active breakage rather than a topology worth knowing about.
func (t remoteTopology) header(style checkpointNoteStyle) string {
	severe := t.pushMismatch() || t.electionErr != ""
	switch {
	case style == noteStyleSentence && severe:
		return "\nWarning: this repo is not syncing checkpoints."
	case style == noteStyleSentence:
		return "\nNote: this repo's remotes make the checkpoint destination ambiguous."
	case severe:
		return "Checkpoint destination: ACTION NEEDED"
	default:
		return "Checkpoint destination: REVIEW"
	}
}

