package cli

import (
	"context"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// describe renders the note for a hand-built topology. Building the struct
// directly keeps these tests on the decision logic — which findings fire and how
// they are worded — rather than on git plumbing, which resolveGitPushRemote and
// the integration tests cover separately.
func describe(t remoteTopology, style checkpointNoteStyle) string {
	var b strings.Builder
	t.describeCheckpointDestination(&b, style)
	return b.String()
}

// twoRemotes is the everyday shape behind this whole file: an origin plus a
// second remote, neither pinned to a checkpoint_remote.
func twoRemotes() []remoteDestination {
	return []remoteDestination{
		{name: "fork", pushURLs: []string{"https://example.com/me/r.git"}},
		{name: "origin", pushURLs: []string{"https://example.com/them/r.git"}},
	}
}

func TestRemoteTopology_OrdinaryRepoSaysNothing(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations: []remoteDestination{{name: "origin", pushURLs: []string{"https://example.com/o/r.git"}}},
		elected:      "origin",
		//nolint:staticcheck // spelled out for symmetry with the other cases
		electedSource: strategy.SyncRemoteSourceDefault,
		pushDest:      "origin",
	}

	assert.Empty(t, describe(topo, noteStyleStatusLabel),
		"the single-remote repo must stay silent; this note is only for repos where the destination is a choice")
}

// TestRemoteTopology_PushMismatchReportsTheFix is the regression for the reported
// bug: pushing to a remote that is not the elected one carries no checkpoint
// data, and doctor has to say so and name the setting that fixes it.
func TestRemoteTopology_PushMismatchReportsTheFix(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations:  twoRemotes(),
		elected:       "origin",
		electedSource: strategy.SyncRemoteSourceDefault,
		pushDest:      "fork",
	}

	out := describe(topo, noteStyleStatusLabel)

	assert.Contains(t, out, "ACTION NEEDED", "a push that carries no checkpoints is breakage, not a topology note")
	assert.Contains(t, out, "NOT carrying checkpoints")
	assert.Contains(t, out, `"fork"`)
	assert.Contains(t, out, `"origin"`)
	assert.Contains(t, out, "checkpoint_push_remote", "the note must name the setting that fixes this")

	// The pre-fix text claimed the opposite of what the code does. Nothing here
	// may reintroduce it.
	assert.NotContains(t, out, "follow whichever remote you push to")
}

// TestRemoteTopology_MismatchWarnsAboutTheOriginReadPath covers the caveat that
// comes with taking the recommended fix: the read paths bootstrap from origin
// only, so pinning elsewhere syncs but does not round-trip.
func TestRemoteTopology_MismatchWarnsAboutTheOriginReadPath(t *testing.T) {
	t.Parallel()

	nonOrigin := describe(remoteTopology{
		destinations: twoRemotes(), elected: "origin",
		electedSource: strategy.SyncRemoteSourceDefault, pushDest: "fork",
	}, noteStyleStatusLabel)
	assert.Contains(t, nonOrigin, "looks at origin", "pinning to a non-origin remote has a read-path consequence")

	// Pushing to origin while checkpoints were pinned elsewhere is still a
	// mismatch, but the fix points back at origin, so the caveat does not apply.
	toOrigin := describe(remoteTopology{
		destinations: twoRemotes(), elected: "fork",
		electedSource: strategy.SyncRemoteSourceConfig, pushDest: "origin",
	}, noteStyleStatusLabel)
	assert.Contains(t, toOrigin, "NOT carrying checkpoints")
	assert.NotContains(t, toOrigin, "not found again from a fresh clone",
		"the read-path caveat is noise when the fix is to sync to origin")
}

// TestRemoteTopology_ConfiguredDestinationIsNotNagged is the regression for the
// misfire: a repo that already set checkpoint_push_remote was still told to go
// and configure a destination.
func TestRemoteTopology_ConfiguredDestinationIsNotNagged(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations:  twoRemotes(),
		elected:       "fork",
		electedSource: strategy.SyncRemoteSourceConfig,
		pushDest:      "fork",
	}

	assert.Empty(t, describe(topo, noteStyleStatusLabel),
		"checkpoint_push_remote is the decision this note asks for; a repo that made it must not be flagged")
}

// TestRemoteTopology_MismatchSurvivesAnExplicitSetting: an explicit
// checkpoint_push_remote settles the *choice*, but if pushes still land
// elsewhere the data loss is real and must be reported anyway.
func TestRemoteTopology_MismatchSurvivesAnExplicitSetting(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations:  twoRemotes(),
		elected:       "backup",
		electedSource: strategy.SyncRemoteSourceConfig,
		pushDest:      "fork",
	}

	assert.Contains(t, describe(topo, noteStyleStatusLabel), "NOT carrying checkpoints")
}

func TestRemoteTopology_ElectionErrorIsReported(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations: twoRemotes(),
		electionErr:  `checkpoint_push_remote "gone" is not a configured git remote; checkpoint sync disabled until fixed`,
		pushDest:     "fork",
	}

	out := describe(topo, noteStyleStatusLabel)
	assert.Contains(t, out, "ACTION NEEDED")
	assert.Contains(t, out, "NOT syncing anywhere")
	assert.Contains(t, out, `"gone"`)
	// A fail-closed election means nothing syncs at all, which supersedes the
	// general "you have several remotes" advice.
	assert.NotContains(t, out, "This repo has 2 remotes")
}

// TestRemoteTopology_SeveralRemotesStateTheElection covers the advisory case:
// nothing is broken, but the destination was decided for the user, so say which
// remote it is instead of the old claim that checkpoints follow the push.
func TestRemoteTopology_SeveralRemotesStateTheElection(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations:  twoRemotes(),
		elected:       "origin",
		electedSource: strategy.SyncRemoteSourceDefault,
		pushDest:      "origin",
	}

	out := describe(topo, noteStyleStatusLabel)
	assert.Contains(t, out, "REVIEW", "an undecided destination is worth reviewing, not an emergency")
	assert.Contains(t, out, "This repo has 2 remotes (fork, origin)")
	assert.Contains(t, out, `Checkpoints sync only to "origin"`)
	assert.Contains(t, out, "checkpoint_push_remote")
	assert.NotContains(t, out, "follow whichever remote you push to",
