// bug: pushing to a remote that is not the elected one carries no checkpoint
// data, and doctor has to say so and name the setting that fixes it.
func TestRemoteTopology_PushMismatchReportsTheFix(t *testing.T) {
	t.Parallel()

	topo := remoteTopology{
		destinations:  twoRemotes(),
		elected:       "origin",
		electedSource: strategy.SyncRemoteSourceDefault,
		pushDest:      "fork",
	}

	out := describe(topo, noteStyleStatusLabel)

	assert.Contains(t, out, "ACTION NEEDED", "a push that carries no checkpoints is breakage, not a topology note")
	assert.Contains(t, out, "NOT carrying checkpoints")
	assert.Contains(t, out, `"fork"`)
	assert.Contains(t, out, `"origin"`)
	assert.Contains(t, out, "checkpoint_push_remote", "the note must name the setting that fixes this")

