// TestMultiPushURL_DestinationNoteSurfaces checks that the ambiguity is
// announced rather than left for a reader of the source: `entire doctor` reports
// it, and it stays silent on an ordinary single-destination repo so the common
// output is unchanged.
//
// The "pushes elsewhere" case is the one that matters most: checkpoint data syncs
// only to the elected remote, so a repo pushing somewhere else is silently not
// syncing, and doctor is where the user finds out. Its wording is asserted
// end-to-end here because the note was once wired up to claim the opposite —
// that checkpoints follow whichever remote you push to.
func TestMultiPushURL_DestinationNoteSurfaces(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		setup  func(env *TestEnv)
		want   []string
		absent []string
	}{
