func (env *TestEnv) PatchSettings(extra map[string]any) {
	env.T.Helper()

	settingsPath := filepath.Join(env.RepoDir, ".entire", paths.SettingsFileName)
	data, err := os.ReadFile(settingsPath)
	if err != nil {
		env.T.Fatalf("failed to read settings: %v", err)
