// MetadataDivergence describes how the local primary metadata ref relates to a
// remote-tracking ref. Diverged is the case no existing check reported: both
// refs advanced since their merge base, so neither contains the other's
// checkpoints and the next fetch from the elected remote rewrites the local ref
// by replaying the local commits (see SafelyAdvanceLocalRef). Distinct from
// disconnected (no merge base at all, IsMetadataDisconnected) and from plain
// ahead/behind, which need no comment.
type MetadataDivergence struct {
	// Local and Remote are the two tips; zero when the respective ref is absent.
	Local  plumbing.Hash
	Remote plumbing.Hash
	// Diverged is true only when both refs exist, differ, share a merge base,
	// and neither is an ancestor of the other.
	Diverged bool
}

// MetadataDivergenceFromRemote classifies the local primary metadata ref
// against remoteRefName. Pure read — it never writes a ref. A missing ref on
// either side, identical tips, a fast-forward either way, or no merge base at
// all all report Diverged false; the disconnected case is
// IsMetadataDisconnected's to report.
func MetadataDivergenceFromRemote(ctx context.Context, repo *git.Repository, remoteRefName plumbing.ReferenceName) (MetadataDivergence, error) {
	var d MetadataDivergence

	refs := checkpoint.ResolveRefs(ctx)
	localRef, err := repo.Reference(refs.Primary, true)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		return d, nil
	}
	if err != nil {
		return d, fmt.Errorf("failed to read local primary metadata ref: %w", err)
	}
	remoteRef, err := repo.Reference(remoteRefName, true)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		return d, nil
	}
	if err != nil {
		return d, fmt.Errorf("failed to read remote metadata ref: %w", err)
	}

	d.Local, d.Remote = localRef.Hash(), remoteRef.Hash()
	if d.Local == d.Remote {
		return d, nil
	}

	repoPath, err := getRepoPath(repo)
	if err != nil {
		return d, err
	}
	mergeBase, err := getMergeBase(ctx, repoPath, d.Local.String(), d.Remote.String())
	if errors.Is(err, errNoMergeBase) {
		return d, nil // disconnected, not diverged
	}
	if err != nil {
		return d, fmt.Errorf("failed to find merge base for %s: %w", refs.Primary, err)
	}

	// Either side containing the merge base is a fast-forward, not a divergence.
	d.Diverged = mergeBase != d.Local && mergeBase != d.Remote
	return d, nil
}

